*,
*:before,
*:after {
  box-sizing: border-box;
}

body {
  font-family: 'Euclid Circular A', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  font-size: 14px;
  margin: 0;
}

/* Euclid Circular A */

/* Semibold */
@font-face {
  font-family: 'Euclid Circular A';
  font-weight: 700;
  font-style: normal;
  src:
    url('https://d2va9gm4j17fy9.cloudfront.net/fonts/euclid-circular/EuclidCircularA-Semibold-WebXL.woff2') format('woff2'),
    url('https://d2va9gm4j17fy9.cloudfront.net/fonts/euclid-circular/EuclidCircularA-Semibold-WebXL.woff') format('woff'),
    url('https://d2va9gm4j17fy9.cloudfront.net/fonts/euclid-circular/EuclidCircularA-Semibold.ttf') format('truetype');
}

/* Semibold Italic */
@font-face {
  font-family: 'Euclid Circular A';
  font-weight: 700;
