 31→export const TreeSelect: React.FC<TreeSelectProps> = ({
 32→  "data-cy": dataCy,
 33→  isVisible = true,
 34→  onChange,
 35→  onFilter,
 36→  onReset,
 37→  setOptionsLabel = () => undefined,
 38→  state,
 39→  tData,
 40→}) => {
 41→  const allValues = getAllValues(tData);
 42→  // removes values not included in tData
 43→  const filteredState = state.filter((value) => allValues.includes(value));
 44→  const optionsLabel = filteredState.includes(ALL_VALUE)
 45→    ? ALL_COPY
 46→    : filteredState
 47→        .reduce(
 48→          // remove children nodes if parent exists in state
 49→          (accum, value) => {
 50→            const { target } = findNode({ value, tData });
 51→            if (target.children) {
 52→              return accum.filter(
 53→                // @ts-expect-error: FIXME. This comment was added by an automated script.
 54→                (v) => !target.children.find((child) => child.value === v),
 55→              );
 56→            }
 57→            return accum;
 58→          },
 59→          [...filteredState],
 60→        )
 61→        .map((value) => findNode({ value, tData }).target.title)
 62→        .join(", ");
 63→
 64→  useEffect(() => {
 65→    setOptionsLabel(optionsLabel);
 66→  }, [optionsLabel, setOptionsLabel]);
 67→
 68→  if (!isVisible) {
 69→    return null;
 70→  }
 71→
 72→  return (
 73→    <CheckboxContainer data-cy={dataCy || "tree-select-options"}>
 74→      {renderCheckboxes({
 75→        state: filteredState,
 76→        tData,
 77→        onChange,
 78→      })}
 79→      {onReset && onFilter && (
 80→        <FilterInputControls
 81→          onClickReset={onReset}
 82→          onClickSubmit={onFilter}
 83→          submitButtonCopy="Filter"
 84→        />
 85→      )}
 86→    </CheckboxContainer>
 87→  );
 88→};
 89→
 90→// depth first traversal checkbox data.
 91→// pushes parent then children to rows array
 92→// keeps track of level for indentation
 93→const renderCheckboxes = ({
 94→  onChange,
 95→  state,
 96→  tData,
 97→}: {
 98→  tData: TreeDataEntry[];
 99→  state: string[];
100→  onChange: (v: [string]) => void;
101→}): React.JSX.Element[] => {
102→  const rows: React.JSX.Element[] = [];
103→  tData.forEach((entry) => {
104→    // @ts-expect-error: FIXME. This comment was added by an automated script.
105→    renderCheckboxesHelper({ rows, data: entry, onChange, state, tData });
106→  });
107→  return rows;
108→};
109→
110→const renderCheckboxesHelper = ({
111→  data,
112→  onChange,
113→  rows,
114→  state,
115→  tData,
116→}: {
117→  rows: React.JSX.Element[];
118→  data: TreeDataEntry;
119→  onChange: (v: string[]) => void;
120→  state: string[];
121→  tData: TreeDataEntry[];
122→}): void => {
123→  // push parent
124→  const onChangeFn = (): void =>
125→    handleOnChange({ state, value: data.value, onChange, tData });
126→  rows.push(
127→    <CheckboxWrapper key={data.key} isAll={data.value === ALL_VALUE} level={0}>
128→      <Checkbox
129→        bold={false}
130→        checked={state.includes(data.value)}
131→        className="cy-checkbox"
132→        data-cy="checkbox"
133→        label={data.title}
134→        onChange={onChangeFn}
135→      />
136→    </CheckboxWrapper>,
137→  );
138→  // then examine children
139→  if (data.children) {
140→    data.children.forEach((child) => {
141→      const onChangeChildFn = (): void =>
142→        handleOnChange({ state, value: child.value, onChange, tData });
143→      rows.push(
144→        <CheckboxWrapper
145→          key={`${data.key}-${child.key}`}
146→          isAll={child.value === ALL_VALUE}
147→          level={1}
148→        >
149→          <Checkbox
150→            bold={false}
151→            checked={state.includes(child.value)}
152→            className="cy-checkbox"
153→            data-cy="checkbox"
154→            label={child.title}
155→            onChange={onChangeChildFn}
156→          />
157→        </CheckboxWrapper>,
158→      );
159→    });
160→  }
161→};
162→
163→// Executes when checkbox is clicked
164→const handleOnChange = ({
165→  onChange,
166→  state,
167→  tData, // callback function
168→  value,
169→}: {
170→  state: string[];
171→  value: string;
172→  onChange: (v: string[]) => void;
173→  tData: TreeDataEntry[];
174→}): void => {
175→  const isAlreadyChecked = state.includes(value); // is checkbox already selected
176→  const { parent, siblings, target } = findNode({ value, tData });
177→  const isParent = target.children;
178→  const isAll = target.value === ALL_VALUE; // is all button clicked
179→  if (!target) {
180→    onChange([...state]);
181→  }
182→  // is all button checked
183→  if (isAll) {
184→    if (isAlreadyChecked) {
185→      onChange([]);
186→    } else {
187→      onChange(getAllValues(tData));
188→    }
189→  } else if (isParent) {
190→    // has list of children
191→    // @ts-expect-error: FIXME. This comment was added by an automated script.
192→    const childrenValues = target.children.map((child) => child.value);
193→    if (isAlreadyChecked) {
194→      onChange(
195→        adjustAll({
196→          resultState: state.filter(
197→            (v) => v !== value && !childrenValues.includes(v),
198→          ),
199→          tData,
200→        }),
201→      );
202→    } else {
203→      const resultState = Array.from(
204→        new Set([...state, value, ...childrenValues]),
205→      );
206→      onChange(adjustAll({ resultState, tData }));
207→    }
208→  } else {
209→    // does not have list of children, could be child
210→    const parentValue = parent ? parent.value : "";
211→    if (isAlreadyChecked) {
212→      onChange(
213→        adjustAll({
214→          resultState: state.filter((v) => v !== value && v !== parentValue),
215→          tData,
216→        }),
217→      );
218→    } else {
219→      let siblingsChecked = true;
220→      siblings.forEach((sibling) => {
221→        siblingsChecked = siblingsChecked && state.includes(sibling.value);
222→      });
223→      const shouldCheckParent = parentValue && siblingsChecked;
224→      // use set in case parent.value already exists in state
225→      const resultState = Array.from(
226→        new Set(
227→          [...state, value].concat(shouldCheckParent ? [parentValue] : []),
228→        ),
229→      );
230→      onChange(adjustAll({ resultState, tData }));
231→    }
232→  }
233→};
234→
235→// selects or deselects the All checkbox depending on current options
236→const adjustAll = ({
237→  resultState,
238→  tData,
239→}: {
240→  resultState: string[];
241→  tData: TreeDataEntry[];
242→}): string[] => {
243→  const allValues = getAllValues(tData).filter((value) => value !== ALL_VALUE);
244→  const resultStateHasAllValues = allValues.reduce(
245→    (accum, value) => accum && resultState.includes(value),
246→    true,
247→  );
248→  // convert to set in case all exists in URL when its not supposed to
249→  const resultStateSet = new Set(resultState);
250→  if (resultStateHasAllValues) {
251→    resultStateSet.add(ALL_VALUE);
252→  } else {
253→    resultStateSet.delete(ALL_VALUE);
254→  }
255→  return Array.from(resultStateSet);
256→};
257→
258→interface FindNodeResult {
259→  target: TreeDataEntry;
260→  parent: TreeDataEntry;
261→  siblings: TreeDataEntry[] | TreeDataChildEntry[];
262→}
263→
264→const findNode = ({
265→  tData,
266→  value,
267→}: {
268→  value: string;
269→  tData: TreeDataEntry[];
270→}): FindNodeResult => {
271→  for (const curr of tData) {
272→    if (curr.value === value) {
273→      return {
274→        target: curr,
275→        // @ts-expect-error: FIXME. This comment was added by an automated script.
276→        parent: null,
277→        siblings: tData.filter((v) => v.value !== value),
278→      };
279→    }
280→    if (curr.children) {
281→      const child = curr.children.find((c) => c.value === value);
282→      if (child) {
283→        return {
284→          target: child,
285→          parent: curr,
286→          siblings: curr.children.filter((c) => c.value !== value),
287→        };
288→      }
289→    }
290→  }
291→  return {
292→    // @ts-expect-error: FIXME. This comment was added by an automated script.
293→    target: null,
294→    // @ts-expect-error: FIXME. This comment was added by an automated script.
295→    parent: null,
296→    siblings: [],
297→  };
298→};
299→
300→// returns all values in tData from parents and children
301→const getAllValues = (tData: TreeDataEntry[]): string[] =>
302→  tData.reduce((accum, currNode) => {
303→    const childrenValues = currNode.children
304→      ? currNode.children.map((child) => child.value)
305→      : [];
306→    // @ts-expect-error: FIXME. This comment was added by an automated script.
307→    return accum.concat([currNode.value]).concat(childrenValues);
308→  }, []);
309→
310→const CheckboxWrapper = styled.div<{ level: number; isAll: boolean }>`
311→  padding-left: ${({ level }) => `${level}em`};
312→  padding-top: ${size.xxs};
313→  padding-bottom: ${size.xxs};
314→  ${({ isAll }) => isAll && `border-bottom: 1px solid ${gray.light2};`}
315→`;
316→
317→const CheckboxContainer = styled.div`
318→  min-width: 150px; // need to set this as side effect of getPopupContainer
319→  font-weight: normal; // need to set this as side effect of getPopupContainer
320→`;
321→

  1→import { useCallback, useEffect, useMemo, useRef } from "react";
  2→import { ParseOptions } from "query-string";
  3→import { useLocation, useNavigate } from "react-router-dom";
  4→import { conditionalToArray } from "../../utils/array";
  5→import { parseQueryString, stringifyQuery } from "../../utils/query-string";
  6→
  7→type QueryParams = { [key: string]: unknown };
  8→type QueryParamsUpdater = QueryParams | ((current: QueryParams) => QueryParams);
  9→type SetQueryParams = (params: QueryParamsUpdater) => void;
 10→
 11→/**
 12→ * `useQueryParams` returns all of the query params that exist in the url.
 13→ * @param parseOptions - options which define how to parse params from the url (optional)
 14→ * @returns a tuple containing the parsed query params and a function to set the query params.
 15→ * The setter supports both direct values and functional updates (like useState).
 16→ */
 17→const useQueryParams = (
 18→  parseOptions?: ParseOptions,
 19→): readonly [QueryParams, SetQueryParams] => {
 20→  const location = useLocation();
 21→  const navigate = useNavigate();
 22→
 23→  // The url colors=red%2Cblue,green becomes colors=red%2Cblue%2Cgreen
 24→  // after using URLSearchParams.toString(), so we lose the contex of `,`.
 25→  // So `parseQueryString` can't tell the difference and we end up breaking the filters
 26→  const rawSearch = location.search.replace(/^\?/, "");
 27→
 28→  const searchParamsObject = useMemo(
 29→    () => parseQueryString(rawSearch, parseOptions ?? {}),
 30→    [rawSearch, parseOptions],
 31→  );
 32→
 33→  // Use a ref to track current params so the setter can read fresh values
 34→  // without needing searchParams in its dependency array.
 35→  // This is necessary because react-router-dom's setSearchParams is not stable.
 36→  const paramsRef = useRef(searchParamsObject);
 37→  useEffect(() => {
 38→    paramsRef.current = searchParamsObject;
 39→  }, [searchParamsObject]);
 40→
 41→  const setQueryString = useCallback(
 42→    (updater: QueryParamsUpdater) => {
 43→      const currentParams = paramsRef.current;
 44→      const newParams =
 45→        typeof updater === "function" ? updater(currentParams) : updater;
 46→
 47→      const stringifiedQuery = stringifyQuery(newParams, {
 48→        skipEmptyString: false,
 49→      });
 50→      navigate(`?${stringifiedQuery}`, { replace: true });
 51→    },
 52→    [navigate],
 53→  );
 54→
 55→  return [searchParamsObject, setQueryString] as const;
 56→};
 57→
 58→/**
 59→ * `useQueryParam` allows you to interact with a query param in the same way you would use a useState hook.
 60→ * The first argument is the name of the query param. The second argument is the initial value of the query param.
 61→ * `useQueryParam` will default to the second argument if the query param is not present in the url.
 62→ * @param param - the name of the query param
 63→ * @param defaultParam - the default value of the query param
 64→ * @param parseOptions - options which define how to parse params from the url (optional)
 65→ * @returns a tuple containing the parsed query param and a function to set the query param.
 66→ * The setter has a stable identity and will not change between renders.
 67→ */
 68→const useQueryParam = <T>(
 69→  param: string,
 70→  defaultParam: T,
 71→  parseOptions?: ParseOptions,
 72→): readonly [T, (set: T) => void] => {
 73→  const [searchParams, setSearchParams] = useQueryParams(parseOptions);
 74→
 75→  // Capture the initial defaultParam to avoid recomputation when callers
 76→  // pass inline arrays/objects (e.g., useQueryParam("filters", []))
 77→  const defaultParamRef = useRef(defaultParam);
 78→
 79→  const setQueryParam = useCallback(
 80→    (value: T) => {
 81→      setSearchParams((current) => ({
 82→        ...current,
 83→        [param]: value,
 84→      }));
 85→    },
 86→    [setSearchParams, param],
 87→  );
 88→
 89→  // This lint error is a false positive: https://github.com/facebook/react/issues/34775
 90→  /* eslint-disable react-hooks/refs */
 91→  const queryParam = useMemo(
 92→    () =>
 93→      searchParams[param] !== undefined
 94→        ? (conditionalToArray(
 95→            searchParams[param],
 96→            Array.isArray(defaultParamRef.current),
 97→          ) as unknown as T)
 98→        : defaultParamRef.current,
 99→    [searchParams, param],
100→  );
101→
102→  return [queryParam, setQueryParam] as const;
103→  /* eslint-enable react-hooks/refs */
104→};
105→
106→export { useQueryParams, useQueryParam };
107→

 1→import { useRef, useState } from "react";
 2→import styled from "@emotion/styled";
 3→import { GuideCue, GuideCueProps } from "@leafygreen-ui/guide-cue";
 4→import { palette } from "@leafygreen-ui/palette";
 5→import { differenceInDays } from "date-fns";
 6→import Cookies from "js-cookie";
 7→import { size } from "../../constants/tokens";
 8→import Icon from "../Icon";
 9→
10→type Props = {
11→  activeDays?: number;
12→  cookieName: string;
13→  loading?: boolean;
14→};
15→
16→/**
17→ * ExpiringAnnouncementTooltip displays a clickable info icon with a popover.
18→ * On first view, the popover opens automatically. Once dismissed, a cookie is set
19→ * and the popover stays closed on future visits. The info icon remains visible
20→ * for `activeDays` (default 8) after first dismissal, then disappears entirely.
21→ * @param props - React props
22→ * @param props.activeDays - number of days the info icon will persist after the tooltip is first viewed
23→ * @param props.cookieName - cookie associated with the view state
24→ * @param props.loading - whether data present in the tooltip is loading, helps avoid flickering tooltip
25→ * @returns React component
26→ */
27→export const ExpiringAnnouncementTooltip: React.FC<
28→  Props & Pick<GuideCueProps, "children" | "title" | "tooltipAlign">
29→> = ({ activeDays = 8, cookieName, loading = false, ...guideCueProps }) => {
30→  const now = new Date();
31→  const infoRef = useRef(null);
32→
33→  const seenTooltipCookie: string | undefined = Cookies.get(cookieName);
34→  const neverSeenTooltip = !seenTooltipCookie;
35→  const seenTooltipDate = seenTooltipCookie ? new Date(seenTooltipCookie) : now;
36→
37→  const [open, setOpen] = useState(neverSeenTooltip);
38→
39→  const close = () => {
40→    setOpen(false);
41→
42→    if (neverSeenTooltip) {
43→      Cookies.set(cookieName, seenTooltipDate.toString(), { expires: 365 });
44→    }
45→  };
46→
47→  return !loading &&
48→    (neverSeenTooltip ||
49→      differenceInDays(now, seenTooltipDate) < activeDays) ? (
50→    <>
51→      <IconContainer ref={infoRef}>
52→        <Icon
53→          data-cy="announcement-tooltip-trigger"
54→          fill={palette.gray.dark2}
55→          glyph="InfoWithCircle"
56→          onClick={() => setOpen((o) => !o)}
57→        />
58→      </IconContainer>
59→      <GuideCue
60→        currentStep={1}
61→        numberOfSteps={1}
62→        onDismiss={close}
63→        onPrimaryButtonClick={close}
64→        open={open}
65→        refEl={infoRef}
66→        setOpen={setOpen}
67→        {...guideCueProps}
68→      />
69→    </>
70→  ) : null;
71→};
72→
73→const IconContainer = styled.div`
74→  cursor: pointer;
75→  padding-left: ${size.xxs};
76→`;
