import { useRef, useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, waitFor } from 'storybook/test';
import { within } from 'storybook/test';
import { Button } from '@leafygreen-ui/button';
import Popconfirm from '.';

const meta = {
  component: Popconfirm,
  tags: ['ai-generated'],
} satisfies Meta<typeof Popconfirm>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  render: () => {
    const triggerRef = useRef<HTMLButtonElement>(null);
    const [open, setOpen] = useState(false);
    return (
      <div style={{ padding: 100 }}>
        <Button ref={triggerRef} onClick={() => setOpen(true)}>
          Delete Item
        </Button>
        <Popconfirm
          open={open}
          setOpen={setOpen}
          refEl={triggerRef}
          onConfirm={() => setOpen(false)}
        >
          Are you sure you want to delete this item?
        </Popconfirm>
      </div>
    );
  },
  play: async ({ canvas, userEvent, canvasElement }) => {
    const trigger = canvas.getByRole('button', { name: /delete item/i });
    await expect(trigger).toBeVisible();
    await userEvent.click(trigger);
    const body = within(canvasElement.ownerDocument.body);
    await waitFor(() =>
      expect(body.getByText(/are you sure/i)).toBeVisible(),
    );
  },
};

export const WithCustomConfirmText: Story = {
  render: () => {
    const triggerRef = useRef<HTMLButtonElement>(null);
    const [open, setOpen] = useState(false);
    return (
      <div style={{ padding: 100 }}>
        <Button ref={triggerRef} onClick={() => setOpen(true)}>
          Restart Task
        </Button>
        <Popconfirm
          open={open}
          setOpen={setOpen}
          refEl={triggerRef}
          confirmText="Restart"
          onConfirm={() => setOpen(false)}
        >
          Restart this task?
        </Popconfirm>
      </div>
    );
  },
  play: async ({ canvas, userEvent, canvasElement }) => {
    const trigger = canvas.getByRole('button', { name: /restart task/i });
    await userEvent.click(trigger);
    const body = within(canvasElement.ownerDocument.body);
    await waitFor(() =>
      expect(body.getByText(/restart this task/i)).toBeVisible(),
    );
  },
};

export const ConfirmDisabled: Story = {
  render: () => {
    const triggerRef = useRef<HTMLButtonElement>(null);
    const [open, setOpen] = useState(false);
    return (
      <div style={{ padding: 100 }}>
        <Button ref={triggerRef} onClick={() => setOpen(true)}>
          Action
        </Button>
        <Popconfirm
          open={open}
          setOpen={setOpen}
          refEl={triggerRef}
          confirmDisabled
          onConfirm={() => setOpen(false)}
        >
          Confirm is disabled.
        </Popconfirm>
      </div>
    );
  },
  play: async ({ canvas, userEvent, canvasElement }) => {
    await userEvent.click(canvas.getByRole('button', { name: /action/i }));
    const body = within(canvasElement.ownerDocument.body);
    await waitFor(() =>
      expect(body.getByText(/confirm is disabled/i)).toBeVisible(),
    );
  },
};

import { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect } from 'storybook/test';
import { TreeSelect, TreeDataEntry } from './TreeSelect';

const sampleData: TreeDataEntry[] = [
  { title: 'All', value: 'all', key: 'all' },
  {
    title: 'Compile',
    value: 'compile',
    key: 'compile',
    children: [
      { title: 'Compile Linux', value: 'compile-linux', key: 'compile-linux' },
      { title: 'Compile macOS', value: 'compile-macos', key: 'compile-macos' },
    ],
  },
  {
    title: 'Test',
    value: 'test',
    key: 'test',
    children: [
      { title: 'Unit Tests', value: 'unit-tests', key: 'unit-tests' },
      {
        title: 'Integration Tests',
        value: 'integration-tests',
        key: 'integration-tests',
      },
    ],
  },
];

const meta = {
  component: TreeSelect,
  tags: ['ai-generated'],
} satisfies Meta<typeof TreeSelect>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  render: () => {
    const [state, setState] = useState<string[]>([]);
    return <TreeSelect state={state} tData={sampleData} onChange={setState} />;
  },
  play: async ({ canvas }) => {
    const checkboxes = canvas.getAllByRole('checkbox');
    await expect(checkboxes.length).toBeGreaterThan(0);
  },
};

export const WithPreselection: Story = {
  render: () => {
    const [state, setState] = useState<string[]>([
      'all',
      'compile',
      'compile-linux',
      'compile-macos',
      'test',
      'unit-tests',
      'integration-tests',
    ]);
    return <TreeSelect state={state} tData={sampleData} onChange={setState} />;
  },
  play: async ({ canvas }) => {
    const checkboxes = canvas.getAllByRole('checkbox');
    await expect(checkboxes[0]).toBeChecked();
  },
};

export const Interactive: Story = {
  render: () => {
    const [state, setState] = useState<string[]>([]);
    return <TreeSelect state={state} tData={sampleData} onChange={setState} />;
  },
  play: async ({ canvas, userEvent }) => {
    // Click the label text "Compile" to toggle the checkbox
    // (native checkbox input has pointer-events: none in LeafyGreen)
    const compileLabel = canvas.getByText('Compile');
    await userEvent.click(compileLabel);
    const checkboxes = canvas.getAllByRole('checkbox');
    // Compile parent (index 1, after "All") should now be checked
    await expect(checkboxes[1]).toBeChecked();
  },
};

