  render: () => {
    const [page, setPage] = useState(0);
    return (
      <Pagination
        currentPage={page}
        totalResults={100}
        pageSize={10}
        onChange={setPage}
      />
    );
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('1 / 10')).toBeVisible();
  },
};

